-- =========================================================================
-- SCRIPT AJUSTADO COM TRATAMENTO DE CONFLITO DE CHAVE ÚNICA (UNIQUE CONSTRAINT)
-- =========================================================================
WITH frequencias_origem AS (
    -- 1. Busca todas as frequências ativas da turma de origem (830012)
    SELECT 
        fa.id_frequencia,
        fa.id_turma,
        fa.id_discente,
        fa.data
    FROM ensino.frequencia_aluno fa
    INNER JOIN ensino.turma t ON t.id_turma = fa.id_turma
    WHERE fa.id_turma = 830012
      AND t.id_turma_serie = 95789029
      AND t.ano = 2026
),
frequencias_destino AS (
    -- 2. Busca todas as combinações de (discente, data) que JÁ EXISTEM na turma de destino (853602)
    SELECT id_discente, data
    FROM ensino.frequencia_aluno
    WHERE id_turma = 853602
),
frequencias_sem_conflito AS (
    -- 3. Seleciona apenas as frequências de origem que NÃO causam duplicidade na turma de destino
    SELECT fo.*
    FROM frequencias_origem fo
    LEFT JOIN frequencias_destino fd 
           ON fd.id_discente = fo.id_discente 
          AND fd.data = fo.data
    WHERE fd.id_discente IS NULL
)
-- 4. Gera a contagem e os scripts de Solução e Backup agrupados com STRING_AGG
SELECT 
    COUNT(fsc.id_frequencia) AS total_registos_sem_conflito,
    'UPDATE ensino.frequencia_aluno SET id_turma = 853602 WHERE id_frequencia IN (' || 
        STRING_AGG(fsc.id_frequencia::TEXT, ', ') || ');' AS solucao_script,
    'UPDATE ensino.frequencia_aluno SET id_turma = ' || fsc.id_turma || ' WHERE id_frequencia IN (' || 
        STRING_AGG(fsc.id_frequencia::TEXT, ', ') || ');' AS backup_script
FROM frequencias_sem_conflito fsc
GROUP BY fsc.id_turma;

begin;

