SELECT 
    COUNT(fa.id_frequencia) AS total_registos_afetados,
    'UPDATE ensino.frequencia_aluno SET id_turma = 853602 WHERE id_frequencia IN (' || string_agg(fa.id_frequencia::TEXT, ', ') || ');' AS solucao,
    'UPDATE ensino.frequencia_aluno SET id_turma = ' || fa.id_turma || ' WHERE id_frequencia IN (' || string_agg(fa.id_frequencia::TEXT, ', ') || ');' AS backup
FROM ensino.frequencia_aluno fa
INNER JOIN ensino.turma t ON t.id_turma = fa.id_turma
WHERE fa.id_turma = 830012
  AND t.id_turma_serie = 95789029
  AND t.ano = 2026
  -- REGRA DE SEGURANÇA SIMPLES: Ignora registros que já existem na turma de destino (853602)
  AND NOT EXISTS (
      SELECT 1 
      FROM ensino.frequencia_aluno fa_dest 
      WHERE fa_dest.id_turma = 853602 
        AND fa_dest.id_discente = fa.id_discente 
        AND fa_dest.data = fa.data
  )
GROUP BY fa.id_turma;